import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type UserRole = 'DENTIST' | 'PATIENT' | 'GUEST';

export enum CavitySeverity {
  MILD = 'Mild',
  MODERATE = 'Moderate',
  SEVERE = 'Severe'
}

export interface CavityDetection {
  id: string;
  box: [number, number, number, number]; // [ymin, xmin, ymax, xmax] normalized 0-1000
  severity: CavitySeverity;
  confidence: number;
}

export interface DiagnosticReport {
  id: string;
  patientName: string;
  dentistName: string;
  date: string;
  originalImage: string;
  cavities: CavityDetection[];
  summary: string;
}

export interface User {
  id: string;
  fullName: string;
  email: string;
  role: UserRole;
  clinicName?: string;
  qualification?: string;
  age?: number;
  gender?: string;
  contact?: string;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CavityDetection, CavitySeverity } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const detectCavities = async (base64Image: string): Promise<CavityDetection[]> => {
  const model = "gemini-3-flash-preview";

  const response = await ai.models.generateContent({
    model,
    contents: [
      {
        parts: [
          {
            text: `Act as a professional dental radiologist. Analyze this dental X-ray for cavities (dental caries). 
            Identify all visible cavities and return a JSON array of objects.
            Each object must include:
            1. 'box': [ymin, xmin, ymax, xmax] coordinates normalized to 0-1000.
            2. 'severity': One of 'Mild', 'Moderate', or 'Severe'.
            3. 'confidence': A number between 0 and 1.

            Focus on radiolucent areas indicative of enamel or dentin decay. 
            If no cavities are found, return an empty array.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image.split(',')[1] // remove data prefix
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            box: {
              type: Type.ARRAY,
              items: { type: Type.NUMBER },
              description: "Bounding box [ymin, xmin, ymax, xmax] normalized 0-1000"
            },
            severity: {
              type: Type.STRING,
              enum: [CavitySeverity.MILD, CavitySeverity.MODERATE, CavitySeverity.SEVERE]
            },
            confidence: {
              type: Type.NUMBER
            }
          },
          required: ["box", "severity", "confidence"]
        }
      }
    }
  });

  try {
    const data = JSON.parse(response.text || "[]");
    return data.map((d: any, index: number) => ({
      ...d,
      id: `cavity-${index}-${Date.now()}`
    }));
  } catch (error) {
    console.error("Failed to parse cavity detection result:", error);
    return [];
  }
};

import { jsPDF } from "jspdf";
import { DiagnosticReport, CavitySeverity } from "../types";

export const generatePDFReport = async (report: DiagnosticReport) => {
  const doc = new jsPDF();
  const primaryColor = "#0d9488"; // Teal-600

  // Header
  doc.setFillColor(primaryColor);
  doc.rect(0, 0, 210, 40, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(24);
  doc.text("DENTAL DIAGNOSTIC REPORT", 105, 25, { align: "center" });

  // Patient Info
  doc.setTextColor(0, 0, 0);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Patient Information:", 20, 50);
  doc.setFont("helvetica", "normal");
  doc.text(`Name: ${report.patientName}`, 20, 60);
  doc.text(`Date: ${report.date}`, 20, 70);

  // Dentist Info
  doc.setFont("helvetica", "bold");
  doc.text("Consultant Dentist:", 120, 50);
  doc.setFont("helvetica", "normal");
  doc.text(`Dr. ${report.dentistName}`, 120, 60);
  doc.text(`Clinic: Smart Dental AI Lab`, 120, 70);

  // Results Section
  doc.setDrawColor(200, 200, 200);
  doc.line(20, 80, 190, 80);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Diagnostic Results", 20, 95);

  doc.setFontSize(12);
  doc.setFont("helvetica", "normal");
  doc.text(`Total Cavities Detected: ${report.cavities.length}`, 20, 105);

  let yOffset = 115;
  report.cavities.forEach((cavity, index) => {
    const color = cavity.severity === CavitySeverity.SEVERE ? "#ef4444" : 
                  cavity.severity === CavitySeverity.MODERATE ? "#f59e0b" : "#10b981";

    doc.setTextColor(0, 0, 0);
    doc.text(`${index + 1}.`, 20, yOffset);
    doc.setTextColor(color);
    doc.text(`${cavity.severity} Cavity`, 30, yOffset);
    doc.setTextColor(100, 100, 100);
    doc.text(`Confidence: ${(cavity.confidence * 100).toFixed(1)}%`, 80, yOffset);
    yOffset += 10;
  });

  // Summary
  doc.setTextColor(0, 0, 0);
  doc.setFont("helvetica", "bold");
  doc.text("Expert Summary:", 20, yOffset + 10);
  doc.setFont("helvetica", "normal");
  const splitText = doc.splitTextToSize(report.summary, 170);
  doc.text(splitText, 20, yOffset + 20);

  // Footer
  doc.setFontSize(10);
  doc.setTextColor(150, 150, 150);
  doc.text("This is an AI-assisted diagnostic report. Please consult with your dentist for final treatment plans.", 105, 280, { align: "center" });

  doc.save(`Dental_Report_${report.patientName.replace(/\s/g, '_')}.pdf`);
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import LandingPage from './pages/LandingPage';
import AuthPage from './pages/AuthPage';
import DashboardPage from './pages/DashboardPage';
import Navigation from './components/Navigation';
import { User, AuthState, UserRole } from './types';

const App: React.FC = () => {
  const [auth, setAuth] = useState<AuthState>({
    user: null,
    isAuthenticated: false
  });

  // Simulated session persistence
  useEffect(() => {
    const storedUser = localStorage.getItem('dental_user');
    if (storedUser) {
      setAuth({ user: JSON.parse(storedUser), isAuthenticated: true });
    }
  }, []);

  const login = (user: User) => {
    setAuth({ user, isAuthenticated: true });
    localStorage.setItem('dental_user', JSON.stringify(user));
  };

  const logout = () => {
    setAuth({ user: null, isAuthenticated: false });
    localStorage.removeItem('dental_user');
  };

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col">
        <Navigation auth={auth} onLogout={logout} />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<LandingPage />} />
            <Route path="/login/:role" element={<AuthPage mode="login" onLogin={login} />} />
            <Route path="/register/:role" element={<AuthPage mode="register" onLogin={login} />} />
            <Route 
              path="/dashboard" 
              element={auth.isAuthenticated ? <DashboardPage auth={auth} /> : <Navigate to="/" />} 
            />
          </Routes>
        </main>
        <footer className="bg-slate-900 text-slate-400 py-8 px-4 text-center">
          <p>© 2024 Smart Dental Imaging Project. All rights reserved.</p>
          <p className="text-sm mt-2 font-mono opacity-50 italic">Empowering diagnostics with Artificial Intelligence</p>
        </footer>
      </div>
    </HashRouter>
  );
};

export default App;

