import { GoogleGenAI, Type } from "@google/genai";
import { CavityDetection, CavitySeverity } from "../types";

// Always use named parameter for apiKey and use process.env.API_KEY directly
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const detectCavities = async (base64Image: string): Promise<CavityDetection[]> => {
  const model = "gemini-3-flash-preview";

  // Use the recommended contents structure { parts: [...] }
  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          text: `Act as a professional dental radiologist. Analyze this dental X-ray for cavities (dental caries). 
          Identify all visible cavities and return a JSON array of objects.
          Each object must include:
          1. 'box': [ymin, xmin, ymax, xmax] coordinates normalized to 0-1000.
          2. 'severity': One of 'Mild', 'Moderate', or 'Severe'.
          3. 'confidence': A number between 0 and 1.

          Focus on radiolucent areas indicative of enamel or dentin decay. 
          If no cavities are found, return an empty array.`
        },
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image.split(',')[1] // remove data prefix
          }
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            box: {
              type: Type.ARRAY,
              items: { type: Type.NUMBER },
              description: "Bounding box [ymin, xmin, ymax, xmax] normalized 0-1000"
            },
            severity: {
              type: Type.STRING,
              enum: [CavitySeverity.MILD, CavitySeverity.MODERATE, CavitySeverity.SEVERE]
            },
            confidence: {
              type: Type.NUMBER
            }
          },
          required: ["box", "severity", "confidence"]
        }
      }
    }
  });

  try {
    // Access response.text directly (property, not a method)
    const data = JSON.parse(response.text || "[]");
    return data.map((d: any, index: number) => ({
      ...d,
      id: `cavity-${index}-${Date.now()}`
    }));
  } catch (error) {
    console.error("Failed to parse cavity detection result:", error);
    return [];
  }
};

