  user: User | null;
  isAuthenticated: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CavityDetection, CavitySeverity } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const detectCavities = async (base64Image: string): Promise<CavityDetection[]> => {
  const model = "gemini-3-flash-preview";

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          text: `Act as a professional dental radiologist. Analyze this dental X-ray for cavities (dental caries). 
          Identify all visible cavities and return a JSON array of objects.

          Classification Rules for 'extent' (clinical percentage of decay):
          - 'Low': 1-40% extent.
          - 'Moderate': 41-80% extent.
          - 'High': 81-100% extent.

          Each object must include:
          1. 'box': [ymin, xmin, ymax, xmax] coordinates normalized to 0-1000.
          2. 'severity': One of: 'Low', 'Moderate', 'High'.
          3. 'extent': The estimated clinical percentage within the range of the assigned severity (e.g., if Moderate, pick a number between 41 and 80).
          4. 'confidence': A number between 0 and 1 representing AI detection confidence.

          If no cavities are found, return an empty array [].`
        },
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image.split(',')[1]
          }
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            box: {
              type: Type.ARRAY,
              items: { type: Type.NUMBER },
              description: "Bounding box [ymin, xmin, ymax, xmax] normalized 0-1000"
            },
            severity: {
              type: Type.STRING,
              enum: [CavitySeverity.LOW, CavitySeverity.MODERATE, CavitySeverity.HIGH]
            },
            extent: {
              type: Type.INTEGER,
              description: "Clinical percentage of decay (1-100)"
            },
            confidence: {
              type: Type.NUMBER,
              description: "AI confidence (0.0 - 1.0)"
            }
          },
          required: ["box", "severity", "extent", "confidence"]
        }
      }
    }
  });

  try {
    const data = JSON.parse(response.text || "[]");
    return data.map((d: any, index: number) => ({
      ...d,
      id: `cavity-${index}-${Date.now()}`
    }));
  } catch (error) {
    console.error("Failed to parse cavity detection result:", error);
    return [];
  }
};

import React from 'react';
import { CavityDetection, CavitySeverity } from '../types';
import { AlertTriangle, CheckCircle } from 'lucide-react';

interface CavityResultsProps {
  detections: CavityDetection[];
  image: string;
}

const CavityResults: React.FC<CavityResultsProps> = ({ detections, image }) => {
  const getSeverityColor = (sev: CavitySeverity) => {
    switch (sev) {
      case CavitySeverity.HIGH: return "#ef4444"; // Red
      case CavitySeverity.MODERATE: return "#f59e0b"; // Amber
      case CavitySeverity.LOW: return "#10b981"; // Emerald
      default: return "#94a3b8";
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center">
          <div className={`p-2 rounded-lg mr-3 ${detections.length > 0 ? 'bg-amber-100 text-amber-600' : 'bg-green-100 text-green-600'}`}>
            {detections.length > 0 ? <AlertTriangle size={20} /> : <CheckCircle size={20} />}
          </div>
          <div>
            <p className="text-sm font-bold text-slate-400 uppercase tracking-wider">Analysis Result</p>
            <p className="text-xl font-bold text-slate-800">
              {detections.length > 0 ? `${detections.length} Cavities Found` : "Clear Scan"}
            </p>
          </div>
        </div>
      </div>

      {/* Main Analysis Image */}
      <div className="relative rounded-xl overflow-hidden shadow-inner bg-slate-900 border border-slate-200">
        <img src={image} alt="Analyzed" className="w-full h-auto opacity-70" />
        <svg 
          viewBox="0 0 1000 1000" 
          className="absolute inset-0 w-full h-full pointer-events-none"
          preserveAspectRatio="none"
        >
          {detections.map((d) => (
            <React.Fragment key={d.id}>
              {/* Bounding Box */}
              <rect
                x={d.box[1]}
                y={d.box[0]}
                width={d.box[3] - d.box[1]}
                height={d.box[2] - d.box[0]}
                fill="transparent"
                stroke={getSeverityColor(d.severity)}
                strokeWidth="8"
                className="animate-pulse"
              />
              {/* Label: Severity (Extent%) */}
              <g>
                <rect 
                  x={d.box[1]} 
                  y={d.box[0] - 50} 
                  width="280" 
                  height="50" 
                  fill={getSeverityColor(d.severity)}
                  rx="4"
                />
                <text
                  x={d.box[1] + 10}
                  y={d.box[0] - 15}
                  fill="white"
                  fontSize="32"
                  fontWeight="bold"
                >
                  {d.severity} ({d.extent}%)
                </text>
              </g>
            </React.Fragment>
          ))}
        </svg>
      </div>

      {/* Result Detail Cards */}
      <div className="space-y-3">
        {detections.map((d, i) => (
          <div key={d.id} className="p-4 bg-slate-50 border border-slate-100 rounded-xl flex justify-between items-center group hover:border-teal-200 transition-all">
            <div className="flex items-center">
              <span className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold mr-3">#{i + 1}</span>
              <div>
                <p className="font-bold text-slate-800">{d.severity} Severity ({d.extent}%)</p>
                <div className="flex items-center space-x-2">
                  <span className="text-[10px] bg-slate-200 px-1.5 py-0.5 rounded uppercase font-bold text-slate-500">
                    AI Confidence: {(d.confidence * 100).toFixed(0)}%
                  </span>
                </div>
              </div>
            </div>
            <div className={`w-3 h-3 rounded-full`} style={{ backgroundColor: getSeverityColor(d.severity) }} />
          </div>
        ))}
        {detections.length === 0 && (
          <div className="p-8 text-center text-slate-500 italic">
            Patient scan appears normal with no visible decay.
          </div>
        )}
      </div>
    </div>
  );
};

export default CavityResults;

import { jsPDF } from "jspdf";
import { DiagnosticReport, CavitySeverity } from "../types";

export const generatePDFReport = async (report: DiagnosticReport) => {
  const doc = new jsPDF();
  const primaryColor = "#0d9488"; // Teal-600

  // --- Page 1: Data & Summary ---
  doc.setFillColor(primaryColor);
  doc.rect(0, 0, 210, 40, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(24);
  doc.text("DENTAL DIAGNOSTIC REPORT", 105, 25, { align: "center" });

  doc.setTextColor(0, 0, 0);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Patient Information:", 20, 50);
  doc.setFont("helvetica", "normal");
  doc.text(`Name: ${report.patientName}`, 20, 60);
  doc.text(`Date: ${report.date}`, 20, 70);

  doc.setFont("helvetica", "bold");
  doc.text("Consultant Dentist:", 120, 50);
  doc.setFont("helvetica", "normal");
  doc.text(`Dr. ${report.dentistName}`, 120, 60);
  doc.text(`Clinic: Smart Dental AI Lab`, 120, 70);

  doc.setDrawColor(200, 200, 200);
  doc.line(20, 80, 190, 80);
  doc.setFontSize(16);
  doc.setFont("helvetica", "bold");
  doc.text("Diagnostic Summary", 20, 95);

  doc.setFontSize(12);
  doc.setFont("helvetica", "normal");
  doc.text(`Total Cavities Detected: ${report.cavities.length}`, 20, 105);

  let yOffset = 115;
  report.cavities.forEach((cavity, index) => {
    const color = cavity.severity === CavitySeverity.HIGH ? "#ef4444" : 
                  cavity.severity === CavitySeverity.MODERATE ? "#f59e0b" : "#10b981";

    doc.setTextColor(0, 0, 0);
    doc.text(`${index + 1}.`, 20, yOffset);
    doc.setTextColor(color);
    doc.text(`${cavity.severity} Severity (${cavity.extent}%)`, 30, yOffset);
    doc.setTextColor(100, 100, 100);
    doc.text(`AI Confidence: ${(cavity.confidence * 100).toFixed(1)}%`, 110, yOffset);
    yOffset += 10;
  });

  doc.setTextColor(0, 0, 0);
  doc.setFont("helvetica", "bold");
  doc.text("Clinical Notes:", 20, yOffset + 10);
  doc.setFont("helvetica", "normal");
  const splitText = doc.splitTextToSize(report.summary, 170);
  doc.text(splitText, 20, yOffset + 20);

  // --- Page 2: Visual Evidence ---
  doc.addPage();
  doc.setFillColor(primaryColor);
  doc.rect(0, 0, 210, 20, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.text("VISUAL EVIDENCE & ANALYSIS", 105, 13, { align: "center" });

  const imgWidth = 140;
  const imgHeight = 80;
  const centerX = (210 - imgWidth) / 2;

  doc.setTextColor(0, 0, 0);
  doc.setFont("helvetica", "bold");
  doc.text("1. Original Uploaded Image", 20, 35);
  try {
    doc.addImage(report.originalImage, 'JPEG', centerX, 40, imgWidth, imgHeight);
  } catch (e) {
    doc.text("[Image Data Unavailable]", centerX, 80);
  }

  const analyzedY = 140;
  doc.text("2. AI Analyzed Image (Mapping)", 20, analyzedY - 5);
  try {
    doc.addImage(report.originalImage, 'JPEG', centerX, analyzedY, imgWidth, imgHeight);
    report.cavities.forEach(cavity => {
      const [ymin, xmin, ymax, xmax] = cavity.box;
      const rectX = centerX + (xmin / 1000) * imgWidth;
      const rectY = analyzedY + (ymin / 1000) * imgHeight;
      const rectW = ((xmax - xmin) / 1000) * imgWidth;
      const rectH = ((ymax - ymin) / 1000) * imgHeight;
      const color = cavity.severity === CavitySeverity.HIGH ? [239, 68, 68] : 
                    cavity.severity === CavitySeverity.MODERATE ? [245, 158, 11] : [16, 185, 129];
      doc.setDrawColor(color[0], color[1], color[2]);
      doc.setLineWidth(1);
      doc.rect(rectX, rectY, rectW, rectH);
      doc.setFontSize(8);
      doc.setTextColor(color[0], color[1], color[2]);
      doc.text(`${cavity.severity} (${cavity.extent}%)`, rectX, rectY - 1);
    });
  } catch (e) {
    doc.text("[Analysis Visualization Unavailable]", centerX, analyzedY + 40);
  }

  doc.setFontSize(10);
  doc.setTextColor(150, 150, 150);
  doc.text("Smart Dental AI - Professional Diagnostic Report", 105, 285, { align: "center" });
  doc.save(`Dental_Report_${report.patientName.replace(/\s/g, '_')}.pdf`);
};

