import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { User } from '../types';
import { ArrowLeft, User as UserIcon, Mail, Lock, GraduationCap } from 'lucide-react';

interface AuthPageProps {
  mode: 'login' | 'register';
  onLogin: (user: User) => void;
}

const AuthPage: React.FC<AuthPageProps> = ({ mode, onLogin }) => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    qualification: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const mockUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      fullName: formData.fullName || 'Professional User',
      email: formData.email,
      role: 'DENTIST',
      qualification: formData.qualification
    };
    onLogin(mockUser);
    navigate('/dashboard');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <Link to="/" className="inline-flex items-center text-teal-600 hover:text-teal-700 font-medium mb-6">
          <ArrowLeft size={16} className="mr-1" /> Back to Home
        </Link>
        <div className="bg-white p-8 rounded-2xl shadow-xl border border-slate-200">
          <h2 className="text-center text-3xl font-extrabold text-slate-900 mb-2">
            {mode === 'login' ? 'Dentist Sign In' : 'Dentist Registration'}
          </h2>
          <p className="text-center text-slate-500 mb-8 font-medium">
            Professional AI Diagnostic Portal
          </p>

          <form onSubmit={handleSubmit} className="space-y-4">
            {mode === 'register' && (
              <div className="relative">
                <UserIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  placeholder="Full Name"
                  className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-teal-500 outline-none transition-all"
                  required
                  value={formData.fullName}
                  onChange={(e) => setFormData({...formData, fullName: e.target.value})}
                />
              </div>
            )}

            <div className="relative">
              <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="email"
                placeholder="Email Address"
                className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-teal-500 outline-none transition-all"
                required
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
              />
            </div>

            <div className="relative">
              <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="password"
                placeholder="Password"
                className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-teal-500 outline-none transition-all"
                required
              />
            </div>

            {mode === 'register' && (
              <>
                <div className="relative">
                  <GraduationCap className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input
                    type="text"
                    placeholder="Professional Qualification"
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-teal-500 outline-none transition-all"
                    value={formData.qualification}
                    onChange={(e) => setFormData({...formData, qualification: e.target.value})}
                  />
                </div>
              </>
            )}

            <button
              type="submit"
              className="w-full bg-teal-600 text-white font-bold py-3 px-4 rounded-xl shadow-lg hover:bg-teal-700 transition-all transform hover:scale-[1.02] active:scale-[0.98]"
            >
              {mode === 'login' ? 'Dentist Sign In' : 'Register Dentist'}
            </button>
          </form>

          <div className="mt-6 text-center text-sm">
            <p className="text-slate-500">
              {mode === 'login' ? "New practitioner?" : "Already registered?"}
              <Link
                to={mode === 'login' ? "/register" : "/login"}
                className="ml-1 text-teal-600 font-bold hover:underline"
              >
                {mode === 'login' ? 'Create Account' : 'Sign In'}
              </Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
